import { headers } from 'next/headers';

async function getDashboardData() {
  try {
    const headersList = await headers();
    const host = headersList.get('host') || 'localhost:3000';
    const protocol = headersList.get('x-forwarded-proto') || 'http';
    const baseUrl = `${protocol}://${host}`;

    const [analytics, notifications, settings] = await Promise.all([
      fetch(`${baseUrl}/api/analytics`).then((r) => r.json()),
      fetch(`${baseUrl}/api/notifications`).then((r) => r.json()),
      fetch(`${baseUrl}/api/settings`).then((r) => r.json()),
    ]);

    return { analytics, notifications, settings };
  } catch {
    return {
      analytics: { pageViews: 0, uniqueVisitors: 0, bounceRate: 0, avgSessionDuration: 0 },
      notifications: { items: [], unreadCount: 0 },
      settings: { theme: 'light', notifications: true, language: 'en' },
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section>
        <h3>Analytics</h3>
        <p>Page views: {analytics.pageViews}</p>
        <p>Unique visitors: {analytics.uniqueVisitors}</p>
        <p>Bounce rate: {analytics.bounceRate}%</p>
        <p>Avg. session: {analytics.avgSessionDuration}s</p>
      </section>

      <section>
        <h3>Notifications ({notifications.unreadCount} unread)</h3>
        <ul>
          {notifications.items.map((item: { id: string; title: string; message: string; read: boolean }) => (
            <li key={item.id}>
              <strong>{item.title}</strong>: {item.message} {item.read ? '(read)' : '(new)'}
            </li>
          ))}
        </ul>
      </section>

      <section>
        <h3>Settings</h3>
        <p>Theme: {settings.theme}</p>
        <p>Notifications: {settings.notifications ? 'On' : 'Off'}</p>
        <p>Language: {settings.language}</p>
      </section>
    </div>
  );
}

